def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    opp_d = sum(1 for a, b in history if b == 'D')
    my_d = sum(1 for a, b in history if a == 'D')

    # High defection: opponent defects more than 60% of the time
    if opp_d > n * 0.6:
        if n % 10 == 0:
            return 'C'
        return 'D'

    # Low defection: opponent defects less than 15% of the time
    if opp_d <= n * 0.15:
        if n >= 95:
            return 'D'
        if n > 20 and n % 15 == 0:
            return 'D'
        return 'C'

    # Moderate defection: Tit-for-Tat with Apology
    last_my, last_opp = history[-1]
    if last_opp == 'D':
        if last_my == 'D':
            return 'C'
        else:
            return 'D'
    else:
        if last_my == 'D':
            return 'C'
        else:
            if n >= 98:
                return 'D'
            return 'C'
